def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each token is an integer or one of '+', '-', '*', '/'.
    Returns the integer result, where division truncates toward zero.
    """
    stack = []
    for t in tokens:
        if t in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

