code:
def solve(meetings):
    """Return the maximum number of non‑overlapping meetings that can be attended.
    Each meeting should be a two‑element sequence [start, end] with start <= end.
    Meetings that do not satisfy this are ignored.
    A meeting may start exactly when another ends.
    """
    # Filter out malformed or invalid intervals
    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        # Ensure comparable and numeric (int/float)
        if not (isinstance(start, (int, float)) and isinstance(end, (int, float))):
            continue
        if start <= end:
            valid.append((start, end))
    if not valid:
        return 0
    # Greedy by earliest finishing time
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for start, end in valid:
        if start >= last_end:
            count += 1
            last_end = end
    return count

