    # Dynamic programming: dp[i] = min number of coins to make amount i
    # Initialize dp with a sentinel larger than any possible answer.
    max_val = amount + 1  # sentinel (unreachable)
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
