def solve(nested):
    """Flatten a nested structure containing integers.
    The input is expected to be a list, but any nested iterable (list, tuple, set)
    is recursively traversed. Only integer values (excluding booleans) are collected.
    """
    from collections.abc import Iterable
    result = []
    def _flatten(item):
        # Strings and bytes are iterable but should be treated as atomic values
        if isinstance(item, (str, bytes)):
            # Not an integer, ignore
            return
        # If item is an iterable (list, tuple, set, etc.), recurse
        if isinstance(item, Iterable):
            for sub in item:
                _flatten(sub)
        else:
            if isinstance(item, int) and not isinstance(item, bool):
                result.append(item)
    _flatten(nested)
    return result

