def solve(matrix):
    """Return the determinant of a square integer matrix.
    An empty matrix has determinant 1.
    Uses the Bareiss algorithm for exact integer arithmetic.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Make a deep copy to avoid mutating the input
    A = [row[:] for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Find a non-zero pivot in column k at or below row k
        pivot = k
        while pivot < n and A[pivot][k] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != k:
            # Swap rows
            A[k], A[pivot] = A[pivot], A[k]
            det_sign = -det_sign
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update: (A[i][j]*A[k][k] - A[i][k]*A[k][j]) // prev_pivot
                A[i][j] = (A[i][j] * A[k][k] - A[i][k] * A[k][j])
                if k > 0:
                    A[i][j] //= A[k - 1][k - 1]
            A[i][k] = 0
    return det_sign * A[n - 1][n - 1]

