def solve(n):
    """Return the number of prime numbers strictly less than *n*.
    Simple implementation using trial division, suitable for the test ranges.
    Handles non‑positive inputs gracefully.
    """
    if n <= 2:
        return 0
    def is_prime(x):
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        i = 3
        import math
        limit = int(math.isqrt(x))
        while i <= limit:
            if x % i == 0:
                return False
            i += 2
        return True
    count = 0
    for i in range(2, n):
        if is_prime(i):
            count += 1
    return count

