def solve(n, edges):
    import heapq, math
    # Edge cases
    if n == 0:
        return -1
    if n == 1:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        # Assume valid input, but guard against out-of-range indices
        if 0 <= a < n and 0 <= b < n:
            adj[a].append((b, w))
            adj[b].append((a, w))
    INF = math.inf
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1 if dist[n - 1] is INF else dist[n - 1]

